import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  onAuthStateChanged,
  signInWithEmailAndPassword,
  signOut,
} from "firebase/auth";
import {
  collection,
  doc,
  getDoc,
  getDocs,
  onSnapshot,
  query,
  serverTimestamp,
  setDoc,
  updateDoc,
  where,
} from "firebase/firestore";
import { auth, db } from "../services/firebase";
import { normalizeRole } from "../utils/departmentMembership";

const AuthContext = createContext();
const ATTENDANCE_TOLERANCE_MINUTES = 10;
const HEARTBEAT_INTERVAL_MS = 5 * 60 * 1000;
const IDLE_LIMIT_MINUTES = 45;
const IDLE_LIMIT_MS = IDLE_LIMIT_MINUTES * 60 * 1000;
const ACTIVITY_EVENTS = [
  "click",
  "keydown",
  "scroll",
  "mousemove",
  "touchstart",
  "focus",
];

export function AuthProvider({ children }) {
  const [firebaseUser, setFirebaseUser] = useState(null);
  const [profile, setProfile] = useState(null);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeSession, setActiveSession] = useState(null);
  const activeSessionRef = useRef(null);
  const lastRealActivityMillisRef = useRef(Date.now());

  async function loadUserProfile(user) {
    if (!user?.uid) {
      return null;
    }

    const userRef = doc(db, "users", user.uid);
    const userSnapshot = await getDoc(userRef);

    if (!userSnapshot.exists()) {
      console.warn(
        "No existe un documento en Firestore para este UID:",
        user.uid
      );

      return null;
    }

    return {
      id: userSnapshot.id,
      uid: user.uid,
      ...userSnapshot.data(),
    };
  }

  async function refreshProfile() {
    if (!firebaseUser) {
      setProfile(null);
      return null;
    }

    const updatedProfile = await loadUserProfile(firebaseUser);
    setProfile(updatedProfile);

    return updatedProfile;
  }

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setLoading(true);

      try {
        setFirebaseUser(user);

        if (user) {
          const userProfile = await loadUserProfile(user);
          setProfile(userProfile);

          if (userProfile?.active === true) {
            registerAutomaticWorkSession(userProfile).catch((error) => {
              console.error("No se pudo registrar asistencia automática:", error);
            });
          }
        } else {
          setProfile(null);
          setActiveSession(null);
        }
      } catch (error) {
        console.error("Error cargando perfil del usuario:", error);
        setProfile(null);
      } finally {
        setLoading(false);
      }
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (!firebaseUser?.uid) return undefined;

    return onSnapshot(
      doc(db, "users", firebaseUser.uid),
      (userSnapshot) => {
        setProfile(userSnapshot.exists()
          ? { id: userSnapshot.id, uid: firebaseUser.uid, ...userSnapshot.data() }
          : null);
      },
      (error) => {
        console.error("Error sincronizando el perfil del usuario:", error);
      }
    );
  }, [firebaseUser?.uid]);

  useEffect(() => {
    if (!firebaseUser?.uid) {
      return undefined;
    }

    return onSnapshot(
      query(collection(db, "users"), where("active", "==", true)),
      (snapshot) => {
        setUsers(
          snapshot.docs.map((userDoc) => ({
            id: userDoc.id,
            uid: userDoc.id,
            ...userDoc.data(),
          }))
        );
      },
      (error) => {
        console.error("Error sincronizando el directorio de usuarios:", error);
        setUsers([]);
      }
    );
  }, [firebaseUser?.uid]);

  const directoryUsers = useMemo(() => {
    if (!profile) return users;

    const profileId = profile.uid || profile.id;
    const hasCurrentProfile = users.some(
      (user) => user.id === profileId || user.uid === profileId
    );

    return hasCurrentProfile ? users : [profile, ...users];
  }, [profile, users]);


  useEffect(() => {
    activeSessionRef.current = activeSession;
  }, [activeSession]);

  useEffect(() => {
    if (!activeSession?.id) return undefined;

    const registerRealActivity = () => {
      const nowMillis = Date.now();
      const lastRealActivityMillis =
        lastRealActivityMillisRef.current ||
        activeSessionRef.current?.lastRealActivityMillis ||
        nowMillis;

      if (nowMillis - lastRealActivityMillis >= IDLE_LIMIT_MS) {
        return;
      }

      lastRealActivityMillisRef.current = nowMillis;
    };

    registerRealActivity();

    ACTIVITY_EVENTS.forEach((eventName) => {
      window.addEventListener(eventName, registerRealActivity, {
        passive: true,
      });
    });

    return () => {
      ACTIVITY_EVENTS.forEach((eventName) => {
        window.removeEventListener(eventName, registerRealActivity);
      });
    };
  }, [activeSession?.id]);

  useEffect(() => {
    if (!activeSession?.id) return undefined;

    const interval = window.setInterval(() => {
      updateWorkSessionHeartbeat(activeSession).catch((error) => {
        console.error("No se pudo actualizar actividad de jornada:", error);
      });
    }, HEARTBEAT_INTERVAL_MS);

    return () => window.clearInterval(interval);
  }, [activeSession]);

  async function registerAutomaticWorkSession(userProfile) {
    const userId = userProfile.uid || userProfile.id;

    if (!userId) return null;

    const today = new Date();
    const dateValue = getDateValue(today);
    const dayKey = getTodayKey(today);
    const sessionId = `${sanitizeId(userId)}_${dateValue}`;
    const sessionRef = doc(db, "workSessions", sessionId);
    const nowMillis = Date.now();
    const nowTimeText = formatTimeFromDate(new Date(nowMillis));

    const [expectedSchedule, attendanceLocations, currentLocation] = await Promise.all([
      getExpectedScheduleForToday(userId, dayKey, dateValue),
      getActiveAttendanceLocations(),
      getCurrentBrowserLocationSafe(),
    ]);

    const existingSnapshot = await getDoc(sessionRef).catch(() => null);
    const existingData = existingSnapshot?.exists?.() ? existingSnapshot.data() : null;
    const existingIsInactive = Boolean(
      existingData?.isIdle ||
        existingData?.countingStatus === "inactive" ||
        existingData?.effectiveEndMillis
    );

    const locationResult = getLocationValidationResult({
      currentLocation,
      attendanceLocations,
    });

    const hasExpectedSchedule = Boolean(expectedSchedule?.startTime && expectedSchedule?.endTime);
    const expectedMinutes = hasExpectedSchedule
      ? getMinutesBetween(expectedSchedule.startTime, expectedSchedule.endTime)
      : 0;

    const minutesLate = hasExpectedSchedule
      ? Math.max(0, Math.round((nowMillis - getDateTimeMillis(dateValue, expectedSchedule.startTime)) / 60000) - ATTENDANCE_TOLERANCE_MINUTES)
      : 0;

    const canCountAsWorkTime = Boolean(
      hasExpectedSchedule && locationResult.locationStatus === "insideLocation"
    );

    const basePayload = {
      userId,
      userName: userProfile.name || userProfile.email || "Usuario",
      userEmail: userProfile.email || "",
      area: userProfile.area || userProfile.department || userProfile.departmentName || "Sin área",
      role: userProfile.role || "collaborator",
      date: dateValue,
      dayOfWeek: dayKey,
      scheduledStartTime: expectedSchedule?.startTime || "",
      scheduledEndTime: expectedSchedule?.endTime || "",
      expectedMinutes,
      scheduleStatus: expectedSchedule?.status || "noSchedule",
      locationStatus: locationResult.locationStatus,
      locationName: locationResult.locationName || "",
      latitude: currentLocation?.latitude ?? null,
      longitude: currentLocation?.longitude ?? null,
      accuracyMeters: currentLocation?.accuracy ?? null,
      distanceMeters: locationResult.distanceMeters ?? null,
      isCountedAsWorkTime: canCountAsWorkTime,
      status: getWorkSessionStatus({
        canCountAsWorkTime,
        hasExpectedSchedule,
        locationStatus: locationResult.locationStatus,
        minutesLate,
      }),
      minutesLate: canCountAsWorkTime ? minutesLate : 0,
      attemptedAt: serverTimestamp(),
      attemptedAtMillis: nowMillis,
      attemptedTimeText: nowTimeText,
      lastSeenAt: serverTimestamp(),
      lastSeenMillis: nowMillis,
      lastRealActivityAt: new Date(nowMillis),
      lastRealActivityMillis: nowMillis,
      idleLimitMinutes: IDLE_LIMIT_MINUTES,
      isIdle: false,
      countingStatus: "notCounted",
      effectiveEndAt: null,
      effectiveEndMillis: null,
      effectiveEndReason: "",
      updatedAt: serverTimestamp(),
    };

    if (!existingData) {
      basePayload.createdAt = serverTimestamp();
    }

    if (canCountAsWorkTime && !existingData?.isCountedAsWorkTime) {
      basePayload.countingStatus = "active";
      basePayload.checkInAt = serverTimestamp();
      basePayload.checkInMillis = nowMillis;
      basePayload.checkInTimeText = nowTimeText;
      basePayload.checkInSource = "loginLocation";
      basePayload.checkOutAt = null;
      basePayload.checkOutMillis = null;
    }

    if (existingData?.isCountedAsWorkTime) {
      basePayload.isCountedAsWorkTime = true;
      basePayload.checkInMillis = existingData.checkInMillis || nowMillis;
      basePayload.checkInTimeText = existingData.checkInTimeText || nowTimeText;
      basePayload.checkInSource = existingData.checkInSource || "loginLocation";
      basePayload.status = existingData.status || basePayload.status;
      basePayload.minutesLate = existingData.minutesLate || 0;

      if (existingIsInactive) {
        basePayload.isIdle = true;
        basePayload.countingStatus = "inactive";
        basePayload.effectiveEndAt = existingData.effectiveEndAt || null;
        basePayload.effectiveEndMillis = existingData.effectiveEndMillis || null;
        basePayload.effectiveEndReason = existingData.effectiveEndReason || "idle";
      } else {
        basePayload.isIdle = false;
        basePayload.countingStatus = "active";
        basePayload.effectiveEndAt = null;
        basePayload.effectiveEndMillis = null;
        basePayload.effectiveEndReason = "";
      }
    }

    await setDoc(sessionRef, basePayload, { merge: true });

    if (basePayload.isCountedAsWorkTime && !existingIsInactive) {
      const sessionActivityMillis = nowMillis;

      lastRealActivityMillisRef.current = sessionActivityMillis;

      setActiveSession({
        id: sessionId,
        checkInMillis: basePayload.checkInMillis || existingData?.checkInMillis || nowMillis,
        lastRealActivityMillis: sessionActivityMillis,
      });
    } else if (existingIsInactive) {
      setActiveSession(null);
    }

    return sessionId;
  }

  async function updateWorkSessionHeartbeat(sessionData) {
    if (!sessionData?.id) return;

    const nowMillis = Date.now();
    const lastRealActivityMillis =
      lastRealActivityMillisRef.current ||
      sessionData.lastRealActivityMillis ||
      nowMillis;

    if (nowMillis - lastRealActivityMillis >= IDLE_LIMIT_MS) {
      const realWorkedMinutes = sessionData.checkInMillis
        ? Math.max(
            0,
            Math.round((lastRealActivityMillis - sessionData.checkInMillis) / 60000)
          )
        : 0;

      await updateDoc(doc(db, "workSessions", sessionData.id), {
        lastSeenAt: serverTimestamp(),
        lastSeenMillis: nowMillis,
        lastRealActivityAt: new Date(lastRealActivityMillis),
        lastRealActivityMillis,
        idleLimitMinutes: IDLE_LIMIT_MINUTES,
        isIdle: true,
        countingStatus: "inactive",
        effectiveEndAt: new Date(lastRealActivityMillis),
        effectiveEndMillis: lastRealActivityMillis,
        effectiveEndReason: "idle",
        idleDetectedAt: serverTimestamp(),
        idleDetectedMillis: nowMillis,
        realWorkedMinutes,
        updatedAt: serverTimestamp(),
      });

      setActiveSession(null);
      return;
    }

    await updateDoc(doc(db, "workSessions", sessionData.id), {
      lastSeenAt: serverTimestamp(),
      lastSeenMillis: nowMillis,
      lastRealActivityAt: new Date(lastRealActivityMillis),
      lastRealActivityMillis,
      idleLimitMinutes: IDLE_LIMIT_MINUTES,
      isIdle: false,
      countingStatus: "active",
      effectiveEndAt: null,
      effectiveEndMillis: null,
      effectiveEndReason: "",
      updatedAt: serverTimestamp(),
    });
  }

  async function closeActiveWorkSession() {
    if (!activeSession?.id) return;

    const nowMillis = Date.now();
    const lastRealActivityMillis =
      lastRealActivityMillisRef.current ||
      activeSession.lastRealActivityMillis ||
      nowMillis;
    const shouldCloseByIdle = nowMillis - lastRealActivityMillis >= IDLE_LIMIT_MS;
    const effectiveEndMillis = shouldCloseByIdle ? lastRealActivityMillis : nowMillis;
    const realWorkedMinutes = activeSession.checkInMillis
      ? Math.max(0, Math.round((effectiveEndMillis - activeSession.checkInMillis) / 60000))
      : 0;

    try {
      const payload = {
        lastSeenAt: serverTimestamp(),
        lastSeenMillis: nowMillis,
        lastRealActivityAt: new Date(lastRealActivityMillis),
        lastRealActivityMillis,
        realWorkedMinutes,
        updatedAt: serverTimestamp(),
      };

      if (shouldCloseByIdle) {
        payload.isIdle = true;
        payload.countingStatus = "inactive";
        payload.effectiveEndAt = new Date(lastRealActivityMillis);
        payload.effectiveEndMillis = lastRealActivityMillis;
        payload.effectiveEndReason = "idle";
        payload.idleDetectedAt = serverTimestamp();
        payload.idleDetectedMillis = nowMillis;
      } else {
        payload.checkOutAt = serverTimestamp();
        payload.checkOutMillis = nowMillis;
        payload.isIdle = false;
        payload.countingStatus = "closed";
        payload.effectiveEndAt = new Date(nowMillis);
        payload.effectiveEndMillis = nowMillis;
        payload.effectiveEndReason = "logout";
      }

      await updateDoc(doc(db, "workSessions", activeSession.id), payload);
    } catch (error) {
      console.error("No se pudo cerrar la jornada activa:", error);
    }
  }

  async function login(email, password) {
    return signInWithEmailAndPassword(auth, email, password);
  }

  async function logout() {
    await closeActiveWorkSession();
    setActiveSession(null);
    return signOut(auth);
  }

  const role = normalizeRole(profile?.role);

  return (
    <AuthContext.Provider
      value={{
        firebaseUser,
        profile,
        users: directoryUsers,
        loading,
        login,
        logout,
        refreshProfile,

        uid: firebaseUser?.uid || null,
        userEmail: firebaseUser?.email || null,

        isAdmin: role === "admin",
        isCollaborator: role === "collaborator",
        isRequester: role === "requester",

        isActive: profile?.active === true,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}

async function getExpectedScheduleForToday(userId, dayKey, dateValue) {
  const adjustmentsSnapshot = await getDocs(
    query(collection(db, "scheduleAdjustments"), where("userId", "==", userId))
  ).catch(() => null);

  const adjustment = adjustmentsSnapshot?.docs
    ?.map((item) => ({ id: item.id, ...item.data() }))
    ?.filter((item) => item.isActive !== false)
    ?.find((item) => isDateInRangeValue(dateValue, item.startDate, item.endDate));

  if (adjustment) {
    const publicStatus = adjustment.publicStatus || adjustment.type;

    if (["permission", "absence", "dayOff"].includes(publicStatus)) {
      return {
        status: publicStatus,
        startTime: "",
        endTime: "",
      };
    }

    if (adjustment.startTime && adjustment.endTime) {
      return {
        status: "adjusted",
        startTime: adjustment.startTime,
        endTime: adjustment.endTime,
      };
    }
  }

  const scheduleSnapshot = await getDoc(doc(db, "workSchedules", `${sanitizeId(userId)}_${dayKey}`)).catch(
    () => null
  );

  if (!scheduleSnapshot?.exists?.()) {
    return {
      status: "noSchedule",
      startTime: "",
      endTime: "",
    };
  }

  const schedule = scheduleSnapshot.data();

  if (schedule.isActive === false || schedule.isRestDay) {
    return {
      status: schedule.isRestDay ? "rest" : "inactive",
      startTime: "",
      endTime: "",
    };
  }

  return {
    status: "scheduled",
    startTime: schedule.startTime || "",
    endTime: schedule.endTime || "",
  };
}

async function getActiveAttendanceLocations() {
  const snapshot = await getDocs(collection(db, "attendanceLocations")).catch(() => null);

  if (!snapshot) return [];

  return snapshot.docs
    .map((item) => ({ id: item.id, ...item.data() }))
    .filter((location) => location.isActive !== false);
}

function getCurrentBrowserLocationSafe() {
  return new Promise((resolve) => {
    if (!navigator.geolocation) {
      resolve({ status: "locationUnavailable" });
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({
          status: "ok",
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy,
        });
      },
      (error) => {
        resolve({
          status: error.code === 1 ? "locationDenied" : "locationUnavailable",
        });
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 30000,
      }
    );
  });
}

function getLocationValidationResult({ currentLocation, attendanceLocations }) {
  if (!attendanceLocations.length) {
    return { locationStatus: "noLocationsConfigured" };
  }

  if (!currentLocation || currentLocation.status !== "ok") {
    return { locationStatus: currentLocation?.status || "locationUnavailable" };
  }

  const nearest = attendanceLocations
    .map((location) => {
      const distanceMeters = getDistanceMeters(
        currentLocation.latitude,
        currentLocation.longitude,
        Number(location.latitude),
        Number(location.longitude)
      );

      return {
        ...location,
        distanceMeters,
        allowedRadiusMeters: Number(location.allowedRadiusMeters || 150),
      };
    })
    .sort((a, b) => a.distanceMeters - b.distanceMeters)[0];

  if (!nearest) {
    return { locationStatus: "outsideLocation" };
  }

  const insideLocation = nearest.distanceMeters <= nearest.allowedRadiusMeters;

  return {
    locationStatus: insideLocation ? "insideLocation" : "outsideLocation",
    locationName: nearest.name || "Sede autorizada",
    distanceMeters: nearest.distanceMeters,
  };
}

function getWorkSessionStatus({
  canCountAsWorkTime,
  hasExpectedSchedule,
  locationStatus,
  minutesLate,
}) {
  if (!hasExpectedSchedule) return "noSchedule";
  if (!canCountAsWorkTime) return locationStatus || "notCounted";
  if (minutesLate > 0) return "late";
  return "onTime";
}

function getTodayKey(date = new Date()) {
  const keys = [
    "sunday",
    "monday",
    "tuesday",
    "wednesday",
    "thursday",
    "friday",
    "saturday",
  ];

  return keys[date.getDay()];
}

function getDateValue(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

function getDateTimeMillis(dateValue, timeValue) {
  return new Date(`${dateValue}T${timeValue}:00`).getTime();
}

function getMinutesBetween(startTime, endTime) {
  const start = timeToMinutes(startTime);
  const end = timeToMinutes(endTime);

  if (start === null || end === null) return 0;
  if (end >= start) return end - start;
  return 24 * 60 - start + end;
}

function timeToMinutes(value = "") {
  const [hours, minutes] = value.split(":").map(Number);

  if (Number.isNaN(hours) || Number.isNaN(minutes)) return null;

  return hours * 60 + minutes;
}

function formatTimeFromDate(date) {
  return date.toLocaleTimeString("es-MX", {
    hour: "numeric",
    minute: "2-digit",
  });
}

function isDateInRangeValue(targetDate, startDate, endDate) {
  if (!targetDate || !startDate) return false;

  const end = endDate || startDate;

  return targetDate >= startDate && targetDate <= end;
}

function sanitizeId(value = "") {
  return String(value).replaceAll("/", "_");
}

function getDistanceMeters(lat1, lon1, lat2, lon2) {
  if ([lat1, lon1, lat2, lon2].some((value) => Number.isNaN(Number(value)))) {
    return Number.POSITIVE_INFINITY;
  }

  const earthRadiusMeters = 6371000;
  const dLat = toRadians(lat2 - lat1);
  const dLon = toRadians(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRadians(lat1)) *
      Math.cos(toRadians(lat2)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return earthRadiusMeters * c;
}

function toRadians(value) {
  return (Number(value) * Math.PI) / 180;
}

import { useEffect, useMemo, useState } from "react";
import { useAuth } from "../context/AuthContext";
import {
  getActiveProjects,
  softDeleteProject,
} from "../services/projectsService";
import { subscribeToUnreadProjectNotifications } from "../services/notificationsService";
import { calculateAutomaticProgress } from "../utils/progressUtils";
import { buildUnreadActivityByProject } from "../utils/projectNotificationActivity";
import UserAvatar from "../components/UserAvatar";
import ProjectActivityIndicator from "../components/ProjectActivityIndicator";

export default function AllProjects({ onOpenProject, onEditProject }) {
  const { profile, currentUser, firebaseUser, isAdmin } = useAuth();

  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const [deletingProjectId, setDeletingProjectId] = useState("");
  const [unreadProjectNotifications, setUnreadProjectNotifications] = useState([]);

  const [searchText, setSearchText] = useState("");
  const [activeQuickFilter, setActiveQuickFilter] = useState("Todos");
  const [departmentFilter, setDepartmentFilter] = useState("");
  const [responsibleFilter, setResponsibleFilter] = useState("");
  const [priorityFilter, setPriorityFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");

  const [showFullDepartmentSummary, setShowFullDepartmentSummary] =
    useState(false);
  const [showFullRecentProjects, setShowFullRecentProjects] = useState(false);
  const [showFullAlerts, setShowFullAlerts] = useState(false);

  async function loadProjects() {
    setLoading(true);
    setMessage("");

    try {
      const data = await getActiveProjects();
      setProjects(data);
    } catch (error) {
      console.error(error);
      setMessage("No se pudieron cargar todos los proyectos.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadProjects();
  }, []);

  const currentUserId =
    currentUser?.uid ||
    firebaseUser?.uid ||
    profile?.uid ||
    profile?.id ||
    "";

  useEffect(() => {
    return subscribeToUnreadProjectNotifications(
      currentUserId,
      setUnreadProjectNotifications
    );
  }, [currentUserId]);

  const unreadActivityByProject = useMemo(
    () => buildUnreadActivityByProject(unreadProjectNotifications),
    [unreadProjectNotifications]
  );

  async function handleDeleteProject(project) {
    if (!isAdmin) {
      setMessage("No tienes permiso para eliminar proyectos.");
      return;
    }

    const confirmDelete = window.confirm(
      `¿Seguro que deseas eliminar el proyecto "${project.title}"?\n\nNo se borrará definitivamente. Se moverá al historial y podrás restaurarlo después.`
    );

    if (!confirmDelete) return;

    setDeletingProjectId(project.id);
    setMessage("");

    try {
      await softDeleteProject(project.id, profile);
      await loadProjects();
      setMessage("El proyecto fue movido al historial correctamente.");
    } catch (error) {
      console.error(error);
      setMessage(error.message || "No se pudo eliminar el proyecto.");
    } finally {
      setDeletingProjectId("");
    }
  }

  function getDaysDifference(deadline) {
    const date = parseDate(deadline);

    if (!date) return null;

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    date.setHours(0, 0, 0, 0);

    const diff = date.getTime() - today.getTime();

    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  }

  function isClosedProject(project) {
    return (
      project.status === "Finalizado" ||
      project.status === "Terminado" ||
      project.status === "Cancelado" ||
      project.status === "Eliminado" ||
      project.deleted === true
    );
  }

  function isOverdue(project) {
    const days = getDaysDifference(project.deadline);

    return days !== null && days < 0 && !isClosedProject(project);
  }

  function renderDeadlineLabel(project) {
    const days = getDaysDifference(project.deadline);

    if (days === null) return "Sin fecha";
    if (days < 0) return `${Math.abs(days)} día(s) vencido`;
    if (days === 0) return "Vence hoy";

    return `${days} días restantes`;
  }

  const departments = useMemo(() => {
    return [
      ...new Set(
        projects
          .map((project) => getProjectDepartmentName(project))
          .filter(Boolean)
      ),
    ].sort((a, b) => a.localeCompare(b, "es"));
  }, [projects]);

  const responsiblePeople = useMemo(() => {
    return [
      ...new Set(
        projects.map((project) => project.assignedToName).filter(Boolean)
      ),
    ].sort((a, b) => a.localeCompare(b, "es"));
  }, [projects]);

  const filteredProjects = useMemo(() => {
    return projects.filter((project) => {
      const search = searchText.trim().toLowerCase();
      const departmentName = getProjectDepartmentName(project);

      const matchesSearch =
        !search ||
        project.title?.toLowerCase().includes(search) ||
        project.description?.toLowerCase().includes(search) ||
        departmentName.toLowerCase().includes(search) ||
        project.responsibleArea?.toLowerCase().includes(search) ||
        project.assignedToName?.toLowerCase().includes(search);

      const matchesQuick =
        activeQuickFilter === "Todos" ||
        (activeQuickFilter === "En curso" && !isClosedProject(project)) ||
        (activeQuickFilter === "Por revisar" &&
          project.status === "Listo para revisión") ||
        (activeQuickFilter === "Atrasados" && isOverdue(project));

      const matchesDepartment =
        !departmentFilter || departmentName === departmentFilter;

      const matchesResponsible =
        !responsibleFilter || project.assignedToName === responsibleFilter;

      const matchesPriority =
        !priorityFilter || project.priority === priorityFilter;

      const matchesStatus = !statusFilter || project.status === statusFilter;

      return (
        matchesSearch &&
        matchesQuick &&
        matchesDepartment &&
        matchesResponsible &&
        matchesPriority &&
        matchesStatus
      );
    });
  }, [
    projects,
    searchText,
    activeQuickFilter,
    departmentFilter,
    responsibleFilter,
    priorityFilter,
    statusFilter,
  ]);

  const metrics = useMemo(() => {
    const total = projects.length;

    const active = projects.filter((project) => !isClosedProject(project)).length;

    const overdue = projects.filter(isOverdue).length;

    const highPriority = projects.filter(
      (project) => project.priority === "Alta" && !isClosedProject(project)
    ).length;

    const review = projects.filter(
      (project) => project.status === "Listo para revisión"
    ).length;

    return { total, active, overdue, highPriority, review };
  }, [projects]);

  const departmentSummary = useMemo(() => {
    const map = new Map();

    projects.forEach((project) => {
      const department = getProjectDepartmentName(project) || "Sin departamento";

      if (!map.has(department)) {
        map.set(department, {
          department,
          total: 0,
          progressTotal: 0,
        });
      }

      const item = map.get(department);

      item.total += 1;
      item.progressTotal += calculateAutomaticProgress(project);
    });

    return Array.from(map.values())
      .map((item) => ({
        ...item,
        average:
          item.total === 0 ? 0 : Math.round(item.progressTotal / item.total),
      }))
      .sort((a, b) => b.total - a.total);
  }, [projects]);

  const visibleDepartmentSummary = showFullDepartmentSummary
    ? departmentSummary
    : departmentSummary.slice(0, 5);

  const recentProjects = useMemo(() => {
    return projects
      .slice()
      .sort((a, b) => {
        const dateA = parseDate(a.updatedAt || a.createdAt);
        const dateB = parseDate(b.updatedAt || b.createdAt);

        if (!dateA && !dateB) return 0;
        if (!dateA) return 1;
        if (!dateB) return -1;

        return dateB.getTime() - dateA.getTime();
      });
  }, [projects]);

  const visibleRecentProjects = showFullRecentProjects
    ? recentProjects
    : recentProjects.slice(0, 4);

  const alertItems = useMemo(() => {
    const overdueProjects = projects.filter(isOverdue);

    const highPriorityProjects = projects.filter(
      (project) => project.priority === "Alta" && !isClosedProject(project)
    );

    const reviewProjects = projects.filter(
      (project) => project.status === "Listo para revisión"
    );

    const correctionProjects = projects.filter(
      (project) => project.status === "Correcciones solicitadas"
    );

    return [
      {
        type: "red",
        title: `${overdueProjects.length} proyectos atrasados`,
        detail: "Requieren seguimiento inmediato.",
        projects: overdueProjects,
      },
      {
        type: "orange",
        title: `${highPriorityProjects.length} proyectos de alta prioridad`,
        detail: "Enfócate en prioridades estratégicas.",
        projects: highPriorityProjects,
      },
      {
        type: "gold",
        title: `${reviewProjects.length} proyectos por revisar`,
        detail: "Están listos para revisión administrativa.",
        projects: reviewProjects,
      },
      {
        type: "purple",
        title: `${correctionProjects.length} proyectos con correcciones`,
        detail: "Requieren seguimiento después de observaciones.",
        projects: correctionProjects,
      },
    ];
  }, [projects]);

  const visibleAlertItems = showFullAlerts ? alertItems : alertItems.slice(0, 2);

  function clearFilters() {
    setSearchText("");
    setActiveQuickFilter("Todos");
    setDepartmentFilter("");
    setResponsibleFilter("");
    setPriorityFilter("");
    setStatusFilter("");
  }

  if (loading) {
    return (
      <div className="all-projects-redesign">
        <div className="dashboard-loading-card">Cargando proyectos...</div>
      </div>
    );
  }

  return (
    <div className="all-projects-redesign">
      <section className="module-topbar all-projects-module-topbar">
        <div className="module-topbar-main">
          <span className="module-topbar-module-icon">
            <ProjectIcon name="projects" />
          </span>

          <div>
            <p className="module-topbar-kicker">Administración</p>
            <h1>Todos los proyectos</h1>
            <p>
              Supervisa proyectos activos, responsables, avances, alertas y prioridades del área.
            </p>
          </div>
        </div>

        <label className="module-topbar-search all-projects-topbar-search">
          <span>
            <ProjectIcon name="search" />
          </span>
          <input
            type="text"
            placeholder="Buscar proyecto, responsable o departamento..."
            value={searchText}
            onChange={(event) => setSearchText(event.target.value)}
          />
        </label>
      </section>

      {message && <div className="message-box">{message}</div>}

      <section className="all-projects-metrics-grid">
        <ProjectMetric
          icon="folder"
          value={metrics.total}
          title="Total activos"
          detail="Proyectos visibles"
          color="blue"
        />

        <ProjectMetric
          icon="check"
          value={metrics.active}
          title="En operación"
          detail="No cerrados"
          color="green"
        />

        <ProjectMetric
          icon="alert"
          value={metrics.overdue}
          title="Atrasados"
          detail="Requieren seguimiento"
          color="red"
        />

        <ProjectMetric
          icon="flag"
          value={metrics.highPriority}
          title="Alta prioridad"
          detail="Prioridades activas"
          color="orange"
        />

        <ProjectMetric
          icon="review"
          value={metrics.review}
          title="Por revisar"
          detail="Revisión administrativa"
          color="teal"
        />
      </section>

      <section className="all-projects-panel all-projects-alerts-wide-panel">
        <SectionHeader
          icon="alert"
          title="Alertas importantes"
          action={showFullAlerts ? "Ver menos" : "Ver todas"}
          onAction={() => setShowFullAlerts((current) => !current)}
        />

        <div className="all-projects-alert-list all-projects-alert-list-wide">
          {visibleAlertItems.map((alert) => (
            <div
              className={`all-projects-alert-card all-projects-alert-${alert.type}`}
              key={alert.title}
            >
              <strong>{alert.title}</strong>
              <p>{alert.detail}</p>

              {alert.projects.length > 0 && (
                <div className="alert-project-links">
                  {alert.projects.slice(0, 3).map((project) => (
                    <button
                      type="button"
                      key={project.id}
                      onClick={() => onOpenProject(project.id)}
                    >
                      {project.title}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      </section>

      <section className="all-projects-filter-panel">
        <div className="all-projects-filter-top">
          <div className="all-projects-panel-heading compact">
            <span>
              <ProjectIcon name="filter" />
            </span>
            <div>
              <h2>Filtros de trabajo</h2>
              <p>Refina la vista sin salir del tablero.</p>
            </div>
          </div>

          <div className="all-projects-quick-tabs">
            {["Todos", "En curso", "Por revisar", "Atrasados"].map((filter) => (
              <button
                key={filter}
                type="button"
                className={activeQuickFilter === filter ? "active" : ""}
                onClick={() => setActiveQuickFilter(filter)}
              >
                {filter}
                {filter === "Atrasados" && <span className="red-dot" />}
              </button>
            ))}
          </div>

          <button
            type="button"
            className="all-projects-clear-button"
            onClick={clearFilters}
          >
            <ProjectIcon name="refresh" />
            Limpiar filtros
          </button>
        </div>

        <div className="all-projects-filter-grid">
          <SelectFilter
            label="Departamento"
            value={departmentFilter}
            onChange={setDepartmentFilter}
            placeholder="Todos los departamentos"
            options={departments}
          />

          <SelectFilter
            label="Responsable"
            value={responsibleFilter}
            onChange={setResponsibleFilter}
            placeholder="Todos los responsables"
            options={responsiblePeople}
          />

          <SelectFilter
            label="Prioridad"
            value={priorityFilter}
            onChange={setPriorityFilter}
            placeholder="Todas las prioridades"
            options={["Alta", "Media", "Baja"]}
          />

          <SelectFilter
            label="Estado"
            value={statusFilter}
            onChange={setStatusFilter}
            placeholder="Todos los estados"
            options={[
              "Por iniciar",
              "En planeación",
              "En proceso",
              "En espera de información",
              "Listo para revisión",
              "Correcciones solicitadas",
              "Aprobado para entrega",
              "Pausado",
            ]}
          />
        </div>
      </section>

      <div className="all-projects-workspace-grid">
        <main className="all-projects-main-column">
          <section className="all-projects-panel all-projects-table-panel">
            <div className="all-projects-panel-header">
              <div className="all-projects-panel-heading">
                <span>
                  <ProjectIcon name="list" />
                </span>
                <div>
                  <h2>Proyectos registrados</h2>
                  <p>Mostrando {filteredProjects.length} de {projects.length} proyecto(s)</p>
                </div>
              </div>

              <div className="all-projects-count-badge">
                {filteredProjects.length} visibles
              </div>
            </div>

            <div className="visual-table-wrap all-projects-table-wrap">
              <table className="visual-table modern-projects-table all-projects-modern-table">
                <thead>
                  <tr>
                    <th>Proyecto</th>
                    <th>Departamento</th>
                    <th>Responsable</th>
                    <th>Estado</th>
                    <th>Prioridad</th>
                    <th>Fecha límite</th>
                    <th>Avance</th>
                    <th>Acciones</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredProjects.map((project) => {
                    const progress = calculateAutomaticProgress(project);
                    const unreadActivity = unreadActivityByProject[project.id];

                    return (
                      <tr
                        key={project.id}
                        className={unreadActivity ? "project-has-new-activity" : ""}
                      >
                        <td data-label="Proyecto">
                          <div className="project-name-cell all-project-name-cell">
                            <span className="project-table-icon all-project-table-icon">
                              <ProjectIcon name="project" />
                            </span>

                            <div>
                              <strong>{project.title}</strong>
                              <small>{project.id.slice(0, 8).toUpperCase()}</small>
                              <ProjectActivityIndicator
                                activity={unreadActivity}
                                compact
                              />
                            </div>
                          </div>
                        </td>

                        <td data-label="Departamento">{getProjectDepartmentName(project)}</td>

                        <td data-label="Responsable">
                          <div className="collaborator-cell">
                            <span className="avatar-mini all-projects-responsible-avatar">
                              <UserAvatar
                                userId={project.assignedToUid || project.assignedToId}
                                name={project.assignedToName || "Sin responsable"}
                              />
                            </span>

                            {project.assignedToName || "Sin responsable"}
                          </div>
                        </td>

                        <td data-label="Estado">
                          <Badge color={isOverdue(project) ? "red" : "blue"}>
                            {isOverdue(project)
                              ? "Atrasado"
                              : project.status || "Sin estado"}
                          </Badge>
                        </td>

                        <td data-label="Prioridad">
                          <Badge
                            color={
                              project.priority === "Alta"
                                ? "orange"
                                : project.priority === "Media"
                                ? "gold"
                                : "green"
                            }
                          >
                            {project.priority || "Sin prioridad"}
                          </Badge>
                        </td>

                        <td data-label="Fecha límite">
                          <strong>{formatPlainDate(project.deadline)}</strong>
                          <small className={isOverdue(project) ? "danger-text" : ""}>
                            {renderDeadlineLabel(project)}
                          </small>
                        </td>

                        <td data-label="Avance">
                          <div className="table-progress all-projects-progress-cell">
                            <strong>{progress}%</strong>

                            <div className="area-progress-track">
                              <div
                                className="area-progress-fill"
                                style={{ width: `${progress}%` }}
                                role="progressbar"
                                aria-label={`Avance de ${project.title}`}
                                aria-valuemin="0"
                                aria-valuemax="100"
                                aria-valuenow={progress}
                              />
                            </div>
                          </div>
                        </td>

                        <td data-label="Acciones">
                          <div className="table-actions all-projects-table-actions">
                            <button className="project-action-view" type="button" onClick={() => onOpenProject(project.id)} aria-label={`Ver ${project.title}`}>
                              <ProjectIcon name="view" />
                              Ver
                            </button>

                            {onEditProject && (
                              <button className="project-action-edit" type="button" onClick={() => onEditProject(project.id)} aria-label={`Editar ${project.title}`}>
                                <ProjectIcon name="edit" />
                                Editar
                              </button>
                            )}

                            {isAdmin && (
                              <button
                                type="button"
                                className="danger-table-button"
                                disabled={deletingProjectId === project.id}
                                onClick={() => handleDeleteProject(project)}
                              >
                                <ProjectIcon name="trash" />
                                {deletingProjectId === project.id
                                  ? "Eliminando..."
                                  : "Eliminar"}
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>

              {filteredProjects.length === 0 && (
                <EmptyState text="No hay proyectos activos con estos filtros." />
              )}
            </div>
          </section>
        </main>

        <aside className="all-projects-side-column">
          <section className="all-projects-panel all-projects-side-panel">
            <SectionHeader
              icon="department"
              title="Resumen por departamento"
              action={showFullDepartmentSummary ? "Ver menos" : "Ver detalle"}
              onAction={() =>
                setShowFullDepartmentSummary((current) => !current)
              }
            />

            <div className="all-projects-department-list">
              {visibleDepartmentSummary.length === 0 ? (
                <EmptyState text="No hay departamentos para mostrar." />
              ) : (
                visibleDepartmentSummary.map((item) => (
                  <div className="all-projects-department-row" key={item.department}>
                    <div>
                      <strong>{item.department}</strong>
                      <small>{item.total} proyecto(s)</small>
                    </div>

                    <div className="area-progress-track">
                      <div
                        className="area-progress-fill"
                        style={{ width: `${item.average}%` }}
                      />
                    </div>

                    <span>{item.average}%</span>
                  </div>
                ))
              )}
            </div>
          </section>

          <section className="all-projects-panel all-projects-side-panel">
            <SectionHeader
              icon="clock"
              title="Proyectos recientes"
              action={showFullRecentProjects ? "Ver menos" : "Ver todos"}
              onAction={() =>
                setShowFullRecentProjects((current) => !current)
              }
            />

            <div className="all-projects-recent-list">
              {visibleRecentProjects.length === 0 ? (
                <EmptyState text="No hay proyectos recientes." />
              ) : (
                visibleRecentProjects.map((project) => (
                  <button
                    type="button"
                    className={`all-projects-recent-card${
                      unreadActivityByProject[project.id]
                        ? " project-has-new-activity"
                        : ""
                    }`}
                    key={project.id}
                    onClick={() => onOpenProject(project.id)}
                  >
                    <span>
                      <ProjectIcon name="project" />
                    </span>

                    <div>
                      <strong>{project.title}</strong>

                      <div>
                        <Badge color="blue">
                          {project.status || "Sin estado"}
                        </Badge>

                        <small>
                          {formatDate(project.updatedAt || project.createdAt)}
                        </small>
                      </div>
                      <ProjectActivityIndicator
                        activity={unreadActivityByProject[project.id]}
                        compact
                      />
                    </div>
                  </button>
                ))
              )}
            </div>
          </section>

        </aside>
      </div>
    </div>
  );
}

function ProjectMetric({ icon, value, title, detail, color }) {
  return (
    <div className={`all-projects-metric-card ${color}`}>
      <div className="all-projects-metric-icon">
        <ProjectIcon name={icon} />
      </div>

      <div>
        <strong>{value}</strong>
        <span>{title}</span>
        <p>{detail}</p>
      </div>
    </div>
  );
}

function SelectFilter({ label, value, onChange, placeholder, options }) {
  return (
    <label className="select-filter all-projects-select-filter">
      <span>{label}</span>

      <select value={value} onChange={(event) => onChange(event.target.value)}>
        <option value="">{placeholder}</option>

        {options.map((option) => (
          <option value={option} key={option}>
            {option}
          </option>
        ))}
      </select>
    </label>
  );
}

function SectionHeader({ icon, title, action, onAction }) {
  return (
    <div className="all-projects-side-header">
      <div>
        <span>
          <ProjectIcon name={icon} />
        </span>
        <h3>{title}</h3>
      </div>

      {action && (
        <button type="button" onClick={onAction}>
          {action}
        </button>
      )}
    </div>
  );
}

function EmptyState({ text }) {
  return (
    <div className="empty-state all-projects-empty-state">
      <div>
        <ProjectIcon name="empty" />
      </div>
      <p>{text}</p>
    </div>
  );
}

function Badge({ color, children }) {
  return <span className={`visual-badge badge-${color}`}>{children}</span>;
}

