              <option key={priority.value} value={priority.value}>{priority.label}</option>
            ))}
          </select>

          <button
            type="button"
            className="visual-outline-button bug-compact-button"
            onClick={() => {
              setStatusFilter("all");
              setPriorityFilter("all");
              setSearchTerm("");
            }}
