          {sharesLoading ? (
            <p className="drive-shortcut-picker-empty">Cargando...</p>
          ) : shares.length === 0 ? (
            <p className="drive-shortcut-picker-empty">Todavia no compartiste este elemento.</p>
          ) : (
            <ul className="drive-share-chip-list">
              {shares.map((share) => (
