const TECHNICAL_QR_PRINT_STYLE_ID = "technical-qr-label-print-size";

function removeTechnicalQrPrintStyle() {
  if (typeof document === "undefined") return;

  document.getElementById(TECHNICAL_QR_PRINT_STYLE_ID)?.remove();
}

function ensureTechnicalQrPrintStyle() {
  if (typeof document === "undefined") return;

  removeTechnicalQrPrintStyle();

  const style = document.createElement("style");
  style.id = TECHNICAL_QR_PRINT_STYLE_ID;
  style.textContent = `
    @media print {
      @page {
        size: 50mm 30mm;
        margin: 0;
      }
    }
  `;
  document.head.appendChild(style);
}

function waitForTechnicalQrPrintAssets() {
  if (typeof document === "undefined") return Promise.resolve();

  const printImages = Array.from(
    document.querySelectorAll(
      ".technical-qr-single-print-area img, .technical-qr-batch-print-area img"
    )
  );

  if (printImages.length === 0) return Promise.resolve();

  return Promise.race([
    Promise.all(
      printImages.map((image) => {
        if (image.complete && image.naturalWidth > 0) return Promise.resolve();
        if (typeof image.decode === "function") {
          return image.decode().catch(() => undefined);
        }

        return new Promise((resolve) => {
          image.addEventListener("load", resolve, { once: true });
          image.addEventListener("error", resolve, { once: true });
        });
      })
    ),
    new Promise((resolve) => window.setTimeout(resolve, 350)),
  ]);
}

function loadHtml5QrcodeLibrary() {
  if (typeof window === "undefined") {
    return Promise.reject(new Error("El navegador no está disponible."));
  }

  if (window.Html5Qrcode) {
    return Promise.resolve(window.Html5Qrcode);
  }

  return new Promise((resolve, reject) => {
    const existingScript = document.getElementById(HTML5_QRCODE_SCRIPT_ID);

    if (existingScript) {
      existingScript.addEventListener("load", () => resolve(window.Html5Qrcode), {
        once: true,
      });
      existingScript.addEventListener(
        "error",
        () => reject(new Error("No se pudo cargar el lector de códigos.")),
        { once: true }
      );
      return;
    }

    const script = document.createElement("script");
    script.id = HTML5_QRCODE_SCRIPT_ID;
    script.src = HTML5_QRCODE_CDN_URL;
    script.async = true;

    script.onload = () => {
      if (window.Html5Qrcode) {
        resolve(window.Html5Qrcode);
        return;
      }

      reject(new Error("El lector de códigos no quedó disponible."));
    };

    script.onerror = () => {
      reject(new Error("No se pudo cargar el lector de códigos."));
    };

    document.body.appendChild(script);
  });
}

