    }

    closeAssetForm();

    if (tabId === "ubicaciones-tecnicas" && !selectedLocationId && technicalLocations.length > 0) {
      setSelectedLocationId(technicalLocations[0].id);
    }

    setActiveTab(tabId);

    if (typeof window !== "undefined") {
      localStorage.setItem("technicalSupportActiveTab", tabId);
    }
