        <path d="M17 3l4 4" />
      </>
    ),
    devices: (
      <>
        <rect x="4" y="5" width="16" height="11" rx="2" />
        <path d="M9 20h6" />
        <path d="M12 16v4" />
        <path d="M8 9h8" />
      </>
    ),
    spares: (
      <>
        <path d="M7 7h10v10H7z" />
        <path d="M9 2v3" />
        <path d="M15 2v3" />
        <path d="M9 19v3" />
        <path d="M15 19v3" />
        <path d="M2 9h3" />
        <path d="M2 15h3" />
        <path d="M19 9h3" />
        <path d="M19 15h3" />
      </>
    ),
    tools: (
